#!/usr/bin/env bash
# Screenshot the main screens in the real WebKit engine and check that taps draw marks where they land.
#   tests/with-servers.sh tests/webkit-all.sh OUTDIR
OUT="${1:-visual-out/webkit}"; mkdir -p "$OUT"
B="http://localhost:8765/"
shot() { xvfb-run -a /usr/bin/python3.12 tests/webkit-shot.py "$OUT/$1.png" "$B?demo=$2&me=$3" 390 844 "${@:4}" 2>&1 | grep -E "^JS|ERROR"; }
for sc in home invite menu-mid bull-play hangman-play ships-place ships-play dots five decided done-menu lost; do shot "$sc" "$sc" 0; done
# taps: five in a row (select a cell -> a dashed box must appear exactly on that cell)
shot tap-five five 1 --js "(function(){const b=document.querySelector('.five-board');const r=b.getBoundingClientRect();const cell=r.width/21;const R=12,C=9;const x=r.left+(C+.5)*cell,y=r.top+(R+.5)*cell;b.dispatchEvent(new MouseEvent('click',{bubbles:true,clientX:x,clientY:y}));const s=document.querySelector('.five-sel');if(!s)return 'NO SELECTION DRAWN';const q=s.getBoundingClientRect();const dx=Math.abs((q.left+q.width/2)-x),dy=Math.abs((q.top+q.height/2)-y);return 'five: selection drawn, offset from tap '+dx.toFixed(1)+','+dy.toFixed(1)+'px, size '+q.width.toFixed(0)+'x'+q.height.toFixed(0)+', marks '+b.querySelectorAll('svg path').length})()"
# dots: tap between two dots -> one more line
shot tap-dots dots 0 --js "(function(){const me=document.querySelector('.turn.mine');const n0=document.querySelectorAll('.dots-svg g path').length;const p=document.querySelector('.dots-svg polygon');if(!p)return 'dots: not my turn (no tap areas) mine='+!!me;p.dispatchEvent(new MouseEvent('click',{bubbles:true}));const n1=document.querySelectorAll('.dots-svg g path').length;const l=document.querySelector('.dots-svg g path').getBoundingClientRect();return 'dots: lines '+n0+' -> '+n1+', a line is '+l.width.toFixed(0)+'x'+l.height.toFixed(0)+'px'})()"
shot tap-dots1 dots 1 --js "(function(){const n0=document.querySelectorAll('.dots-svg g path').length;const p=document.querySelector('.dots-svg polygon');if(!p)return 'dots(p1): not my turn';p.dispatchEvent(new MouseEvent('click',{bubbles:true}));const n1=document.querySelectorAll('.dots-svg g path').length;return 'dots(p1): lines '+n0+' -> '+n1})()"
# ships: aim at a cell -> dashed circle, fire -> a mark in that cell
for me in 0 1; do shot tap-ships$me ships-play $me --js "(function(){const c=document.querySelector('.board:not(.small) .cell.hot');if(!c)return 'ships(p$me): not my turn';c.click();const sel=document.querySelector('.board:not(.small) .cell.sel svg circle');if(!sel)return 'ships: NO AIM MARK';const q=sel.getBoundingClientRect();const marks0=document.querySelectorAll('.board:not(.small) .cell svg').length;document.querySelector('.board:not(.small) .cell.sel').click();const marks1=document.querySelectorAll('.board:not(.small) .cell svg').length;const cell=document.querySelector('.board:not(.small) .cell').getBoundingClientRect();return 'ships(p$me): aim mark '+q.width.toFixed(0)+'px, cell '+cell.width.toFixed(0)+'x'+cell.height.toFixed(0)+', marks '+marks0+' -> '+marks1})()"; done
